        const active = parsed !== null;
        const vivid = active && parsed.style === "vivid";
        if (active && !style.isConnected) document.head.appendChild(style);
        if (!active && style.isConnected) style.remove();
        if (vivid && !vividStyle.isConnected) document.head.appendChild(vividStyle);
