      ctx.effect(() => ctx.locale.register(SETTINGS_NS, {
        zh,
        en
      }), "dsh-themes: settings section dictionaries");

      let savedTheme = null;
      let rotationClock;
      let editing = false;
      let lastInputAt = -Infinity;
      const previewSkin = (draft) => draft.family ? resolveSkin(draft) :
        `dsh-preview-${draft.mode === "system" ? (darkQuery.matches ? "dark" : "light") : draft.mode}`;
